import { type MouseEvent, useState } from 'react';
import { useText } from '../core/CoreProvider';
import licenses from '../data/licenses.json';
import { Dialog } from './Dialog';
import { Field } from './Field';

interface LicensesProps {
  onClose: () => void;
  onOpenLink: (url: string) => void;
  /** The shipped list by default; tests hand in their own. */
  entries?: LicenseEntry[];
}

/** One third-party component, as `data/licenses.json` lists them (generated by the desktop build). */
export interface LicenseEntry {
  source?: string;
  name: string;
  version: string;
  license: string;
  repository?: string | null;
}

/** The components that ship in the app, grouped by license, with a search over names and licenses. */
export function Licenses({ onClose, onOpenLink, entries = licenses }: LicensesProps) {
  const text = useText();
  const [query, setQuery] = useState('');
  const found = filterLicenses(entries, query);
  const groups = groupByLicense(found);

  function open(event: MouseEvent<HTMLAnchorElement>, url: string) {
    event.preventDefault();
    onOpenLink(url);
  }

  return (
    <Dialog title={text('licenses.title')} onClose={onClose}>
      <p className="m-0 text-[13px] text-ink-muted">{text('licenses.intro')}</p>
      <Field
        label={text('licenses.search')}
        type="search"
        name="licenses"
        autoComplete="off"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      {/* What the search found, for screen readers; the empty sentence is also visible below. */}
      <p role="status" className="absolute h-px w-px overflow-hidden [clip:rect(0_0_0_0)]">
        {found.length === 0 ? text('licenses.empty') : `${found.length} ${text('licenses.found')}`}
      </p>
      <div className="flex max-h-[320px] flex-col gap-3 overflow-y-auto">
        {groups.length === 0 ? (
          <p className="m-0 font-heading text-ink-muted [font-variation-settings:'SOFT'_100]">
            {text('licenses.empty')}
          </p>
        ) : (
          groups.map(([license, entries]) => (
            <section key={license} className="flex flex-col gap-1" aria-label={license}>
              <h3 className="m-0 font-text text-[12px] font-bold tracking-[0.04em] text-ink-muted uppercase">
                {license}
              </h3>
              <ul className="m-0 flex list-none flex-col gap-1 p-0">
                {entries.map((entry) => {
                  const url = linkUrl(entry.repository);
                  return (
                    <li
                      key={`${entry.name}@${entry.version}`}
                      className="flex items-baseline justify-between gap-2 [&_a]:text-navy"
                    >
                      {url ? (
                        <a href={url} rel="noreferrer" onClick={(event) => open(event, url)}>
                          {entry.name}
                        </a>
                      ) : (
                        <span>{entry.name}</span>
                      )}
                      <span className="font-mono text-[12px] text-ink-muted">{entry.version}</span>
                    </li>
                  );
                })}
              </ul>
            </section>
          ))
        )}
      </div>
    </Dialog>
  );
}

/** Only a web address becomes a link; the generated list is data, not something we vouch for. */
function linkUrl(repository: string | null | undefined): string | null {
  return repository?.startsWith('https://') ? repository : null;
}

export function filterLicenses(entries: LicenseEntry[], query: string): LicenseEntry[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return entries;
  return entries.filter(
    (entry) =>
      entry.name.toLowerCase().includes(needle) || entry.license.toLowerCase().includes(needle),
  );
}

/** Licenses in alphabetical order, entries by name inside each. */
export function groupByLicense(entries: LicenseEntry[]): [string, LicenseEntry[]][] {
  const groups = new Map<string, LicenseEntry[]>();
  for (const entry of entries) {
    const group = groups.get(entry.license) ?? [];
    group.push(entry);
    groups.set(entry.license, group);
  }
  return [...groups.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([license, group]) => [license, [...group].sort((a, b) => a.name.localeCompare(b.name))]);
}
